def main() -> int:
    with open(OUT, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(HEADER)
        w.writerows(ROWS)
    from collections import Counter
    c = Counter(r[2] for r in ROWS)
    print(f"Wrote {OUT}: {len(ROWS)} rows, {dict(c)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
